import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const params    = exec.params    ?? {};
  const variables = exec.variables ?? {};

  // monitorName is a workflow variable — validate it separately
  const monitorName = variables.monitorName;
  if (!monitorName || monitorName.trim() === '') {
    throw new Error(
      `Workflow variable 'monitorName' is not set or is empty. ` +
      `Set it in the workflow Variables panel before running.`
    );
  }

  // Remaining required values come from execution parameters
  const required = [
    'targetUrl',
    'frequencyMin',
    'locationIds',
    'applicationId'
  ];

  const missing = required.filter((k) => !params[k]);
  if (missing.length > 0) {
    throw new Error(
      `Missing required workflow parameters: ${missing.join(', ')}. ` +
      `Provide them when triggering the workflow manually or via the API.`
    );
  }

  if (typeof params.frequencyMin !== 'number' || params.frequencyMin < 5) {
    throw new Error(
      `'frequencyMin' must be a number >= 5 (Dynatrace minimum). Got: ${params.frequencyMin}`
    );
  }

  if (!Array.isArray(params.locationIds) || params.locationIds.length === 0) {
    throw new Error(`'locationIds' must be a non-empty array of Dynatrace location entity IDs.`);
  }

  console.log(`[validate_inputs] Validated. monitorName='${monitorName}'.`);
  return { valid: true, monitorName, params };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const params    = exec.params    ?? {};
  const variables = exec.variables ?? {};

  // ── monitorName comes from the workflow variable ───────────────────────
  const monitorName    = variables.monitorName;               // set in Variables panel

  // ── Remaining config from execution parameters ────────────────────────
  const targetUrl      = params.targetUrl;                    // e.g. 'https://app.example.com'
  const frequencyMin   = params.frequencyMin ?? 5;            // Minimum: 5
  const locationIds    = params.locationIds;                  // Array of GEOLOCATION- / SYNTHETIC_LOCATION- IDs
  const applicationId  = params.applicationId;               // APPLICATION-XXXXXXXXXXXXXXXX
  const tags           = params.tags ?? [];                   // Optional string array
  const enabled        = params.enabled ?? true;
  const deviceName     = params.deviceName ?? 'Desktop';
  const orientation    = params.orientation ?? 'landscape';
  const waitFor        = params.waitFor ?? 'page_complete';

  // ── Anomaly detection thresholds ─────────────────────────────────────
  const loadingTimeMs  = params.loadingTimeThresholdMs ?? 10000;
  const affectedLocs   = params.localOutageAffectedLocations ?? 1;
  const consRuns       = params.localOutageConsecutiveRuns ?? 3;

  // ── KPM ───────────────────────────────────────────────────────────────
  const loadActionKpm  = params.loadActionKpm ?? 'VISUALLY_COMPLETE';
  const xhrActionKpm   = params.xhrActionKpm  ?? 'VISUALLY_COMPLETE';

  const payload = {
    type: 'BROWSER',
    name: monitorName,
    enabled,
    frequencyMin,
    locations: locationIds,
    manuallyAssignedApps: [applicationId],
    tags,
    keyPerformanceMetrics: {
      loadActionKpm,
      xhrActionKpm
    },
    anomalyDetection: {
      outageHandling: {
        globalOutage: true,
        localOutage: true,
        localOutagePolicy: {
          affectedLocations: affectedLocs,
          consecutiveRuns: consRuns
        }
      },
      loadingTimeThresholds: {
        enabled: true,
        thresholds: [
          {
            type: 'TOTAL',
            requestIndex: 1,
            valueMs: loadingTimeMs
          }
        ]
      }
    },
    script: {
      type: 'availability',
      version: '1.0',
      configuration: {
        device: {
          deviceName,
          orientation
        }
      },
      events: [
        {
          type: 'navigate',
          description: `Loading of "${targetUrl}"`,
          url: targetUrl,
          wait: {
            waitFor
          }
        }
      ]
    },
    events: []
  };

  console.log(`[build_monitor_payload] Payload for monitor '${monitorName}' constructed.`);
  return { payload };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const httpResult = await exec.result('create_synthetic_monitor');

  // The http-function task surfaces statusCode + body
  const statusCode = httpResult?.statusCode ?? 0;
  const body       = httpResult?.body ?? {};

  if (statusCode === 200 || statusCode === 201) {
    const entityId = body.entityId ?? body.monitorId ?? 'UNKNOWN';
    console.log(`[verify_and_log_result] Monitor created successfully. entityId: ${entityId}`);
    return {
      success: true,
      entityId,
      statusCode,
      monitorUrl: `${process.env['DT_TENANT_URL']}/#synthetics/monitors/${entityId}`
    };
  }

  // Treat any non-2xx as a failure
  const errMessage = body.error?.message ?? body.message ?? JSON.stringify(body);
  throw new Error(
    `Synthetic monitor creation failed. HTTP ${statusCode}: ${errMessage}`
  );
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ execution_id }) {
  const exec = await execution(execution_id);
  const taskNames = [
    'validate_inputs',
    'build_monitor_payload',
    'create_synthetic_monitor',
    'verify_and_log_result'
  ];

  for (const taskName of taskNames) {
    try {
      const state = await exec.taskState(taskName);
      if (state === 'FAILED' || state === 'CANCELLED') {
        const err = await exec.result(taskName).catch((e) => ({ _error: e.message }));
        console.error(
          `[handle_error] Task '${taskName}' is in state '${state}'. ` +
          `Details: ${JSON.stringify(err)}`
        );
      }
    } catch (_) {
      // task may not have run; ignore
    }
  }

  return { handled: true };
}
